48	export function parseArgs(argv) {
49	  const byName = new Map(OPTIONS.map((o) => [o.name, o]));
50	  const values = {};
51	  const extras = [];
52	
53	  for (let i = 0; i < argv.length; i++) {
54	    const token = argv[i];
55	
56	    if (token === '-h' || token === '--help') {
57	      printHelp();
58	    }
59	
60	    if (token.startsWith('--')) {
61	      let name = token.slice(2);
62	      let value;
63	      const eq = name.indexOf('=');
64	      if (eq !== -1) {
65	        value = name.slice(eq + 1);
66	        name = name.slice(0, eq);
67	      } else if (i + 1 < argv.length) {
68	        value = argv[++i];
69	      }
70	
71	      const opt = byName.get(name);
72	      if (!opt) {
73	        extras.push(token);
74	        if (eq === -1 && value !== undefined) extras.push(value);
75	        continue;
76	      }
77	
78	      if (value === undefined) {
79	        error(`argument --${name}: expected one argument`);
80	      }
81	
82	      values[name] = opt.type === 'int' ? parseInt_(value, name) : value;
83	    } else {
84	      extras.push(token);
85	    }
86	  }
