3	/**
4	 * Return exactly what Python 3's repr() of a bytes object produces
5	 * (i.e. what print(b'...') outputs) for the given Buffer.
6	 *
7	 * @param {Buffer} buf
8	 * @returns {string}
9	 */
10	export function pyBytesRepr(buf) {
11	  // Quote selection: single quotes unless the data contains a single
12	  // quote and no double quote, in which case double quotes are used.
13	  let hasSingle = false;
14	  let hasDouble = false;
15	  for (const byte of buf) {
16	    if (byte === 0x27) hasSingle = true;
17	    else if (byte === 0x22) hasDouble = true;
18	  }
19	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
20	  const quoteChar = String.fromCharCode(quote);
21	
22	  let out = "b" + quoteChar;
23	  for (const byte of buf) {
24	    if (byte === 0x5c) {
25	      out += "\\\\";
26	    } else if (byte === quote) {
27	      out += "\\" + quoteChar;
28	    } else if (byte === 0x09) {
29	      out += "\\t";
30	    } else if (byte === 0x0a) {
31	      out += "\\n";
32	    } else if (byte === 0x0d) {
33	      out += "\\r";
34	    } else if (byte >= 0x20 && byte <= 0x7e) {
35	      out += String.fromCharCode(byte);
36	    } else {
37	      out += "\\x" + byte.toString(16).padStart(2, "0");
38	    }
39	  }
40	  out += quoteChar;
41	  return out;
42	}

