import { parseArgs } from './lib/argparse.mjs';
import { Int8ul, Int16ul, Bytes, ConstructError } from './lib/construct.mjs';
import { pyBytesRepr } from './lib/pybytes.mjs';

const args = parseArgs(process.argv.slice(2));

try {
  const format1 = Int8ul.build(args.a);
  const format2 = Int16ul.build(args.b);
  const format3 = Bytes(args.d).build(Buffer.from(args.c, 'utf8'));
  const format4 = Int8ul.build(args.f);
  const format5 = Bytes(args.g).build(Buffer.from(args.e, 'utf8'));
  const format6 = Int8ul.build(((args.f + args.g) % 256 + 256) % 256);
  const format7 = Int8ul.build(((args.a + args.b) % 256 + 256) % 256);

  console.log(pyBytesRepr(format1));
  console.log(pyBytesRepr(format2));
  console.log(pyBytesRepr(format3));
  console.log(pyBytesRepr(format4));
  console.log(pyBytesRepr(format5));
  console.log(pyBytesRepr(format6));
  console.log(pyBytesRepr(format7));
} catch (err) {
  if (err instanceof ConstructError) {
    process.stderr.write('construct.core.FormatFieldError: Error in path (building)\n');
    process.stderr.write(String(err.message) + '\n');
    process.exit(1);
  }
  throw err;
}
